from docx import Document
import re

def get_all_text(doc):
    all_text = []
    for para in doc.paragraphs:
        all_text.append(para.text)

    def process_table(table):
        for row in table.rows:
            for cell in row.cells:
                for para in cell.paragraphs:
                    all_text.append(para.text)
                for nested in cell.tables:
                    process_table(nested)

    for table in doc.tables:
        process_table(table)

    return '\n'.join(all_text)

doc = Document('/root/offer_letter_filled.docx')
full_text = get_all_text(doc)

placeholders = re.findall(r'\{\{[^}]+\}\}', full_text)
if placeholders:
    print('WARNING: Unreplaced placeholders found:')
    for p in set(placeholders):
        print(f'  {p}')
else:
    print('SUCCESS: All placeholders have been replaced!')
"

